/* HTTP Basic Auth gate for the whole site.
 *
 * Netlify 内置的站点密码保护属于 Pro 套餐（免费套餐 PATCH site 会返回
 * 422 "Password protection is not available on this plan"），`_headers` 里的
 * Basic-Auth 同样是付费功能。Edge Functions 在免费套餐可用，所以在边缘做拦截。
 *
 * 这是服务端拦截：未通过认证的请求根本拿不到 HTML，不是前端遮罩。
 *
 * 密码从环境变量 SITE_PASSWORD 读取，不写在代码里。用户名不校验，
 * 浏览器弹框里填任意用户名 + 正确密码即可。
 */

const REALM = "VelaSight Architecture Docs";

function unauthorized(): Response {
  return new Response("401 Unauthorized", {
    status: 401,
    headers: {
      "WWW-Authenticate": `Basic realm="${REALM}", charset="UTF-8"`,
      "Content-Type": "text/plain; charset=utf-8",
      "Cache-Control": "no-store",
    },
  });
}

/* 常量时间比较，避免按字符提前返回泄漏信息。 */
function safeEqual(a: string, b: string): boolean {
  const ea = new TextEncoder().encode(a);
  const eb = new TextEncoder().encode(b);
  if (ea.length !== eb.length) {
    return false;
  }

  let diff = 0;
  for (let i = 0; i < ea.length; i++) {
    diff |= ea[i] ^ eb[i];
  }

  return diff === 0;
}

export default async function handler(request: Request): Promise<Response | void> {
  const expected = Netlify.env.get("SITE_PASSWORD");

  /* 没配密码就不拦截，避免把站点锁死在一个空口令上。 */
  if (!expected) {
    return;
  }

  const header = request.headers.get("authorization") ?? "";
  if (!header.toLowerCase().startsWith("basic ")) {
    return unauthorized();
  }

  let decoded: string;
  try {
    decoded = atob(header.slice(6).trim());
  } catch {
    return unauthorized();
  }

  /* 只取第一个冒号后的全部内容作为密码：密码里可以含冒号。 */
  const sep = decoded.indexOf(":");
  const password = sep === -1 ? "" : decoded.slice(sep + 1);

  if (!safeEqual(password, expected)) {
    return unauthorized();
  }

  /* 认证通过：交给后续处理（静态文件）。 */
  return;
}

export const config = { path: "/*" };

