/* ---------------------------------------------------------------------------
 * 模板自带
 * ------------------------------------------------------------------------- */

.md-grid {
    max-width: 90% !important;
}

/* ---------------------------------------------------------------------------
 * 架构图查看器
 *
 * mermaid 渲染出的是内联 SVG，默认被 max-width 限死，既不能放大也不能平移。
 * js/custom.js 会把每个 .mermaid 包进 .vs-diagram，接上 svg-pan-zoom。
 * ------------------------------------------------------------------------- */

.vs-diagram {
    position: relative;
    margin: 1.2em 0;
    border: 1px solid var(--md-default-fg-color--lightest);
    border-radius: .3rem;
    background: var(--md-default-bg-color);
    overflow: hidden;
}

/* 图本体的可视区。高度由 JS 按 viewBox 比例算，这里只兜底。 */
.vs-diagram__stage {
    min-height: 240px;
    cursor: grab;
}

.vs-diagram__stage:active {
    cursor: grabbing;
}

.vs-diagram .mermaid {
    margin: 0;
    height: 100%;
    display: block;
}

/* svg-pan-zoom 需要 SVG 填满容器，模板的 max-width 会打断它 */
.vs-diagram .mermaid > svg {
    max-width: none !important;
    width: 100%;
    height: 100%;
    display: block;
}

/* 工具栏 --------------------------------------------------------------- */

.vs-diagram__bar {
    display: flex;
    align-items: center;
    gap: .3rem;
    padding: .25rem .4rem;
    border-bottom: 1px solid var(--md-default-fg-color--lightest);
    background: var(--md-default-fg-color--lightest);
}

.vs-diagram__btn {
    appearance: none;
    border: 1px solid var(--md-default-fg-color--lighter);
    background: var(--md-default-bg-color);
    color: var(--md-default-fg-color);
    border-radius: .2rem;
    cursor: pointer;
    font-size: .72rem;
    line-height: 1;
    padding: .3rem .5rem;
    min-width: 1.9rem;
    transition: background .15s, border-color .15s;
}

.vs-diagram__btn:hover {
    background: var(--md-accent-fg-color--transparent);
    border-color: var(--md-accent-fg-color);
}

.vs-diagram__btn:focus-visible {
    outline: 2px solid var(--md-accent-fg-color);
    outline-offset: 1px;
}

.vs-diagram__hint {
    margin-left: auto;
    font-size: .64rem;
    color: var(--md-default-fg-color--light);
    padding-right: .2rem;
    user-select: none;
}

/* 全屏 ----------------------------------------------------------------- */

.vs-diagram:fullscreen {
    border: 0;
    border-radius: 0;
    margin: 0;
    display: flex;
    flex-direction: column;
    background: var(--md-default-bg-color);
}

.vs-diagram:fullscreen .vs-diagram__stage {
    flex: 1 1 auto;
    height: auto !important;
}

/* 窄屏上提示文字会挤掉按钮 */
@media screen and (max-width: 44.9375em) {
    .vs-diagram__hint {
        display: none;
    }
}

/* 打印时不需要工具栏 */
@media print {
    .vs-diagram__bar {
        display: none;
    }
    .vs-diagram__stage {
        height: auto !important;
    }
}

/* ---------------------------------------------------------------------------
 * 架构图缩放 / 平移 / 全屏
 *
 * mermaid 渲染出的是内联 SVG，带 viewBox 但被 max-width 限死，页面上只能看到
 * 一张固定大小的图。这里在渲染完成后把 SVG 交给 svg-pan-zoom，并补一条工具栏。
 *
 * 三处需要小心：
 *
 * 1. mermaid 是异步渲染的，脚本执行时 .mermaid 里往往还没有 <svg>。所以用
 *    MutationObserver 等它出现，而不是立刻查询。
 * 2. 滚轮缩放会抢走页面滚动。默认关掉 svg-pan-zoom 自带的滚轮缩放，改成按住
 *    Ctrl/⌘ 才缩放（与地图类嵌入的惯例一致），否则读文档时会被图卡住。
 * 3. 主题开了 navigation.instant，翻页不重载。material 暴露 RxJS 的 document$，
 *    订阅它才能在换页后重新初始化。
 * ------------------------------------------------------------------------- */

(function () {
  "use strict";

  var LIB_URL =
    "https://cdn.jsdelivr.net/npm/[REDACTED_EMAIL]/dist/svg-pan-zoom.min.js";

  var MIN_STAGE_H = 260;   /* 太矮的图看不清结构 */
  var MAX_STAGE_H = 640;   /* 太高的图会顶掉正文 */

  var libPromise = null;

  function loadLib() {
    if (window.svgPanZoom) {
      return Promise.resolve();
    }
    if (libPromise) {
      return libPromise;
    }
    libPromise = new Promise(function (resolve, reject) {
      var s = document.createElement("script");
      s.src = LIB_URL;
      s.async = true;
      s.onload = resolve;
      s.onerror = function () {
        reject(new Error("svg-pan-zoom 加载失败"));
      };
      document.head.appendChild(s);
    });
    return libPromise;
  }

  /* 按 viewBox 的宽高比给可视区一个合理高度。拿不到 viewBox 时退回中间值。 */
  function stageHeight(svg, width) {
    var vb = svg.viewBox && svg.viewBox.baseVal;
    if (!vb || !vb.width || !vb.height || !width) {
      return Math.round((MIN_STAGE_H + MAX_STAGE_H) / 2);
    }
    var h = width * (vb.height / vb.width);
    return Math.round(Math.min(MAX_STAGE_H, Math.max(MIN_STAGE_H, h)));
  }

  function button(label, title, onClick) {
    var b = document.createElement("button");
    b.type = "button";
    b.className = "vs-diagram__btn";
    b.textContent = label;
    b.title = title;
    b.setAttribute("aria-label", title);
    b.addEventListener("click", function (ev) {
      ev.preventDefault();
      onClick();
    });
    return b;
  }

  function enhance(mermaidEl) {
    var svg = mermaidEl.querySelector("svg");
    if (!svg || mermaidEl.dataset.vsZoom === "1") {
      return;
    }
    mermaidEl.dataset.vsZoom = "1";

    /* .mermaid -> [wrap > bar + stage > .mermaid] */
    var wrap = document.createElement("div");
    wrap.className = "vs-diagram";
    var stage = document.createElement("div");
    stage.className = "vs-diagram__stage";

    mermaidEl.parentNode.insertBefore(wrap, mermaidEl);
    wrap.appendChild(stage);
    stage.appendChild(mermaidEl);

    stage.style.height = stageHeight(svg, stage.clientWidth) + "px";

    /* svg-pan-zoom 要求 SVG 填满容器；模板的 max-width 会打断它 */
    svg.setAttribute("width", "100%");
    svg.setAttribute("height", "100%");
    svg.style.maxWidth = "none";

    var pz = window.svgPanZoom(svg, {
      zoomEnabled: true,
      panEnabled: true,
      fit: true,
      center: true,
      contain: false,
      minZoom: 0.3,
      maxZoom: 20,
      zoomScaleSensitivity: 0.3,
      dblClickZoomEnabled: true,
      /* 关掉自带滚轮：默认会抢页面滚动，下面改成 Ctrl+滚轮 */
      mouseWheelZoomEnabled: false,
      controlIconsEnabled: false
    });

    /* Ctrl/⌘ + 滚轮才缩放，其余情况让页面正常滚 */
    stage.addEventListener(
      "wheel",
      function (ev) {
        if (!ev.ctrlKey && !ev.metaKey) {
          return;
        }
        ev.preventDefault();
        if (ev.deltaY < 0) {
          pz.zoomIn();
        } else if (ev.deltaY > 0) {
          pz.zoomOut();
        }
      },
      { passive: false }
    );

    function refit() {
      pz.resize();
      pz.fit();
      pz.center();
    }

    var bar = document.createElement("div");
    bar.className = "vs-diagram__bar";
    bar.appendChild(button("\u2212", "缩小", function () { pz.zoomOut(); }));
    bar.appendChild(button("+", "放大", function () { pz.zoomIn(); }));
    bar.appendChild(button("适应", "还原到适应窗口", refit));

    var fsBtn = button("全屏", "全屏查看（Esc 退出）", function () {
      if (document.fullscreenElement === wrap) {
        document.exitFullscreen();
      } else if (wrap.requestFullscreen) {
        wrap.requestFullscreen();
      }
    });
    /* 不支持 Fullscreen API 时不摆一个点不动的按钮 */
    if (wrap.requestFullscreen) {
      bar.appendChild(fsBtn);
    }

    var hint = document.createElement("span");
    hint.className = "vs-diagram__hint";
    hint.textContent = "拖动平移 · Ctrl + 滚轮缩放 · 双击放大";
    bar.appendChild(hint);

    wrap.insertBefore(bar, stage);

    document.addEventListener("fullscreenchange", function () {
      var full = document.fullscreenElement === wrap;
      fsBtn.textContent = full ? "退出" : "全屏";
      if (!full) {
        stage.style.height = stageHeight(svg, stage.clientWidth) + "px";
      }
      /* 等浏览器完成布局再量尺寸 */
      requestAnimationFrame(refit);
    });

    /* 侧栏折叠、窗口缩放都会改可视区宽度 */
    if (window.ResizeObserver) {
      var ro = new ResizeObserver(function () {
        if (document.fullscreenElement !== wrap) {
          stage.style.height = stageHeight(svg, stage.clientWidth) + "px";
        }
        pz.resize();
      });
      ro.observe(stage);
    }

    refit();
  }

  /* mermaid 异步渲染：等 <svg> 出现再接管，别在还是文本时就查询。 */
  function watch(mermaidEl) {
    if (mermaidEl.dataset.vsWatch === "1") {
      return;
    }
    mermaidEl.dataset.vsWatch = "1";

    if (mermaidEl.querySelector("svg")) {
      loadLib().then(function () { enhance(mermaidEl); }).catch(console.warn);
      return;
    }

    var mo = new MutationObserver(function () {
      if (mermaidEl.querySelector("svg")) {
        mo.disconnect();
        loadLib().then(function () { enhance(mermaidEl); }).catch(console.warn);
      }
    });
    mo.observe(mermaidEl, { childList: true, subtree: true });

    /* 渲染失败就别一直挂着观察器 */
    setTimeout(function () { mo.disconnect(); }, 20000);
  }

  function scan() {
    var list = document.querySelectorAll(".mermaid");
    for (var i = 0; i < list.length; i++) {
      watch(list[i]);
    }
  }

  /* navigation.instant 下翻页不重载，material 用 document$ 通知换页 */
  if (typeof window.document$ !== "undefined" && window.document$.subscribe) {
    window.document$.subscribe(scan);
  } else if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", scan);
  } else {
    scan();
  }
})();

/* 真实浏览器验证架构图的缩放 / 平移 / 全屏。
 * 判据不是"元素存在"，而是 svg-pan-zoom 写在 .svg-pan-zoom_viewport 上的
 * transform 矩阵确实发生了预期方向的变化。
 */
const { firefox } = require("playwright");

const BASE = process.argv[2] || "http://[REDACTED_IP]:8000";

function matrixOf(str) {
  const m = /matrix\(([^)]+)\)/.exec(str || "");
  if (!m) return null;
  const p = m[1].split(/[,\s]+/).map(Number);
  return { scale: p[0], x: p[4], y: p[5] };
}

(async () => {
  const browser = await firefox.launch();
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  const errors = [];
  page.on("pageerror", (e) => errors.push("pageerror: " + e.message));
  page.on("console", (m) => {
    if (m.type() === "error") errors.push("console: " + m.text());
  });

  const results = [];

  /* ---- 1. 每页图都被接管 ---------------------------------------------- */
  const pages = {
    "/": 1,
    "/context-scope/": 1,
    "/building-block-view/": 3,
    "/runtime-view/": 5,
    "/deployment-view/": 2,
    "/cross-cutting-concepts/": 2,
    "/quality-requirements/": 1,
  };

  for (const [path, expected] of Object.entries(pages)) {
    await page.goto(BASE + path, { waitUntil: "load" });
    await page.waitForSelector(".vs-diagram .svg-pan-zoom_viewport", {
      timeout: 30000,
    });
    /* 等全部图都接管完 */
    await page
      .waitForFunction(
        (n) =>
          document.querySelectorAll(".vs-diagram .svg-pan-zoom_viewport")
            .length === n,
        expected,
        { timeout: 30000 }
      )
      .catch(() => {});
    const got = await page.locator(".vs-diagram .svg-pan-zoom_viewport").count();
    const bars = await page.locator(".vs-diagram__bar").count();
    results.push([
      `${path} 图数 ${got}/${expected}，工具栏 ${bars}`,
      got === expected && bars === expected,
    ]);
  }

  /* ---- 2. 放大 / 缩小 / 适应 ------------------------------------------ */
  await page.goto(BASE + "/runtime-view/", { waitUntil: "load" });
  await page.waitForSelector(".vs-diagram .svg-pan-zoom_viewport");
  const vp = page.locator(".vs-diagram .svg-pan-zoom_viewport").first();
  const d0 = page.locator(".vs-diagram").first();

  const read = async () =>
    matrixOf(await vp.evaluate((el) => el.getAttribute("transform")));

  const base = await read();
  results.push([`初始 transform 可读 scale=${base && base.scale}`, !!base]);

  await d0.locator(".vs-diagram__btn", { hasText: "+" }).click();
  const zin = await read();
  results.push([
