  await page.mouse.wheel(0, -240);
  await page.keyboard.up("Control");
  const ctrlWheel = await read();
  results.push([
    `Ctrl+滚轮缩放 ${bareWheel.scale.toFixed(3)} -> ${ctrlWheel.scale.toFixed(3)}`,
    ctrlWheel.scale > bareWheel.scale * 1.05,
  ]);

  /* ---- 5. 全屏按钮存在且可切换 ---------------------------------------- */
  const fsBtn = d0.locator(".vs-diagram__btn", { hasText: /全屏|退出/ });
  const hasFs = (await fsBtn.count()) === 1;
  let fsOk = false;
  if (hasFs) {
    await fsBtn.click();
    await page.waitForTimeout(600);
    fsOk = await page.evaluate(
      () => !!document.fullscreenElement &&
            document.fullscreenElement.classList.contains("vs-diagram")
    );
    if (fsOk) {
      await page.keyboard.press("Escape");
      await page.waitForTimeout(400);
    }
  }
  results.push([`全屏按钮存在并进入全屏 (${fsOk})`, hasFs && fsOk]);

  /* ---- 6. instant navigation 后仍生效 --------------------------------- */
  await page.goto(BASE + "/", { waitUntil: "load" });
  await page.waitForSelector(".vs-diagram .svg-pan-zoom_viewport");
  await page.click('a[href="building-block-view/"], a[href="/building-block-view/"]');
  await page.waitForTimeout(2500);
  const afterNav = await page
    .locator(".vs-diagram .svg-pan-zoom_viewport")
    .count();
  results.push([`instant 翻页后接管 ${afterNav}/3`, afterNav === 3]);

  /* ---- 输出 ----------------------------------------------------------- */
  let fail = 0;
  for (const [label, ok] of results) {
    if (!ok) fail++;
    console.log((ok ? "PASS  " : "FAIL  ") + label);
  }
  if (errors.length) {
    console.log("\n--- 浏览器报错 ---");
    errors.slice(0, 10).forEach((e) => console.log("  " + e));
  }
  console.log(`\n合计 ${results.length - fail}/${results.length} 通过`);

  await browser.close();
  process.exit(fail === 0 && errors.length === 0 ? 0 : 1);
})();

