/* ---------------------------------------------------------------------------
 * 架构图：自行渲染 + 缩放 / 平移 / 全屏
 *
 * 为什么不用主题自带的 mermaid：
 *   mkdocs-material 的 mermaid 集成把 SVG 渲染进 **closed** shadow root
 *   （attachShadow({mode:"closed"})），light DOM 里只留一个空的
 *   <div class="mermaid">。closed 模式下 el.shadowRoot 恒为 null，JS 拿不到
 *   里面的 <svg>，所以「渲染完再后处理」这条路根本走不通。
 *
 *   因此 mkdocs.yml 把 fence 的 class 改成 material 不认识的 vs-mermaid，
 *   由这里自己调 mermaid.render() 输出到 light DOM，再接 svg-pan-zoom。
 *
 * 三处需要小心：
 *   1. 滚轮缩放会抢页面滚动。默认关掉，改成按住 Ctrl/⌘ 才缩放。
 *   2. 主题开了 navigation.instant，翻页不重载，要订阅 material 的 document$。
 *   3. 明暗配色切换时 mermaid 需要按新主题重新渲染，所以保留源码文本。
 * ------------------------------------------------------------------------- */

(function () {
  "use strict";

  var MERMAID_URL =
    "https://cdn.jsdelivr.net/npm/[REDACTED_EMAIL]/dist/mermaid.min.js";
  var PANZOOM_URL =
    "https://cdn.jsdelivr.net/npm/[REDACTED_EMAIL]/dist/svg-pan-zoom.min.js";

  var MIN_STAGE_H = 260;   /* 太矮看不清结构 */
  var MAX_STAGE_H = 640;   /* 太高会顶掉正文 */

  var seq = 0;
  var scriptCache = {};
  var mermaidReady = null;

  function loadScript(url) {
    if (scriptCache[url]) {
      return scriptCache[url];
    }
    scriptCache[url] = new Promise(function (resolve, reject) {
      var s = document.createElement("script");
      s.src = url;
      s.async = true;
      s.onload = resolve;
      s.onerror = function () {
        reject(new Error("加载失败: " + url));
      };
      document.head.appendChild(s);
    });
    return scriptCache[url];
  }

  function isDark() {
    return document.body.getAttribute("data-md-color-scheme") === "slate";
  }

  function initMermaid() {
    /* securityLevel 用 loose：图里用了 <br/> 换行，strict 会把它转义成字面量。
     * 图的内容由本仓库作者撰写，不是外部输入。 */
    window.mermaid.initialize({
      startOnLoad: false,
      theme: isDark() ? "dark" : "default",
      securityLevel: "loose",
      fontFamily: getComputedStyle(document.body).fontFamily || "sans-serif"
    });
  }

  function ensureMermaid() {
    if (!mermaidReady) {
      mermaidReady = loadScript(MERMAID_URL).then(initMermaid);
    }
    return mermaidReady;
  }

  /* 按 viewBox 宽高比给可视区一个合理高度；拿不到就用中间值 */
  function stageHeight(svg, width) {
    var vb = svg.viewBox && svg.viewBox.baseVal;
    if (!vb || !vb.width || !vb.height || !width) {
      return Math.round((MIN_STAGE_H + MAX_STAGE_H) / 2);
    }
    var h = width * (vb.height / vb.width);
    return Math.round(Math.min(MAX_STAGE_H, Math.max(MIN_STAGE_H, h)));
  }

  function button(label, title, onClick) {
    var b = document.createElement("button");
    b.type = "button";
    b.className = "vs-diagram__btn";
    b.textContent = label;
    b.title = title;
    b.setAttribute("aria-label", title);
    b.addEventListener("click", function (ev) {
      ev.preventDefault();
      onClick();
    });
    return b;
  }

  /* 渲染一张图到 stage，成功返回 svg 元素，失败抛错 */
  function renderInto(stage, source) {
    var id = "vsmmd-" + ++seq + "-" + Math.random().toString(36).slice(2, 7);
    return window.mermaid.render(id, source).then(function (res) {
      stage.innerHTML = res.svg;
      var svg = stage.querySelector("svg");
      if (!svg) {
        throw new Error("mermaid 未产出 svg");
      }
      /* mermaid 返回的 svg 带 style="max-width:..."，会打断 svg-pan-zoom */
      svg.removeAttribute("style");
      svg.setAttribute("width", "100%");
      svg.setAttribute("height", "100%");
      if (typeof res.bindFunctions === "function") {
        res.bindFunctions(stage);
      }
      return svg;
    });
  }

  /* 渲染失败时把源码显示出来，不要留一片空白假装正常 */
  function showFailure(wrap, stage, source, err) {
    stage.style.height = "auto";
    stage.classList.add("vs-diagram__stage--failed");
    stage.innerHTML = "";
    var note = document.createElement("p");
    note.className = "vs-diagram__error";
    note.textContent = "图渲染失败：" + ((err && err.message) || err);
    var pre = document.createElement("pre");
    var code = document.createElement("code");
    code.textContent = source;
    pre.appendChild(code);
    stage.appendChild(note);
    stage.appendChild(pre);
    var bar = wrap.querySelector(".vs-diagram__bar");
    if (bar) {
      bar.remove();
    }
  }

  function attachPanZoom(wrap, stage, svg, source) {
    var pz = window.svgPanZoom(svg, {
      zoomEnabled: true,
      panEnabled: true,
      fit: true,
      center: true,
      contain: false,
      minZoom: 0.3,
      maxZoom: 20,
      zoomScaleSensitivity: 0.3,
      dblClickZoomEnabled: true,
      /* 自带滚轮会抢页面滚动，下面换成 Ctrl+滚轮 */
      mouseWheelZoomEnabled: false,
      controlIconsEnabled: false
    });

    stage.addEventListener(
      "wheel",
      function (ev) {
        if (!ev.ctrlKey && !ev.metaKey) {
          return;
        }
        ev.preventDefault();
        if (ev.deltaY < 0) {
          pz.zoomIn();
        } else if (ev.deltaY > 0) {
          pz.zoomOut();
        }
      },
      { passive: false }
    );

    function refit() {
      pz.resize();
      pz.fit();
      pz.center();
    }

    var bar = document.createElement("div");
    bar.className = "vs-diagram__bar";
    bar.appendChild(button("\u2212", "缩小", function () { pz.zoomOut(); }));
    bar.appendChild(button("+", "放大", function () { pz.zoomIn(); }));
    bar.appendChild(button("适应", "还原到适应窗口", refit));

    var fsBtn = button("全屏", "全屏查看（Esc 退出）", function () {
      if (document.fullscreenElement === wrap) {
        document.exitFullscreen();
      } else if (wrap.requestFullscreen) {
        wrap.requestFullscreen();
      }
    });
    if (wrap.requestFullscreen) {
      bar.appendChild(fsBtn);
    }

    var hint = document.createElement("span");
    hint.className = "vs-diagram__hint";
    hint.textContent = "拖动平移 · Ctrl + 滚轮缩放 · 双击放大";
    bar.appendChild(hint);

    wrap.insertBefore(bar, stage);

    function onFsChange() {
      var full = document.fullscreenElement === wrap;
      fsBtn.textContent = full ? "退出" : "全屏";
      if (!full) {
        stage.style.height = stageHeight(svg, stage.clientWidth) + "px";
      }
      requestAnimationFrame(refit);
    }
    document.addEventListener("fullscreenchange", onFsChange);

    if (window.ResizeObserver) {
      var ro = new ResizeObserver(function () {
        if (document.fullscreenElement !== wrap) {
          stage.style.height = stageHeight(svg, stage.clientWidth) + "px";
        }
        pz.resize();
      });
      ro.observe(stage);
    }

    wrap._vsRefit = refit;
    wrap._vsSource = source;
    refit();
  }

  function build(pre) {
    if (pre.dataset.vsDone === "1") {
      return;
    }
    pre.dataset.vsDone = "1";

    var code = pre.querySelector("code");
    var source = (code ? code.textContent : pre.textContent) || "";
    if (!source.trim()) {
      return;
    }

    var wrap = document.createElement("div");
    wrap.className = "vs-diagram";
    var stage = document.createElement("div");
    stage.className = "vs-diagram__stage";

    pre.parentNode.insertBefore(wrap, pre);
    wrap.appendChild(stage);

    /* 源码留在 DOM 里（隐藏），配色切换时要按新主题重渲染 */
    pre.classList.add("vs-diagram__source");
    wrap.appendChild(pre);

    Promise.all([ensureMermaid(), loadScript(PANZOOM_URL)])
      .then(function () {
        return renderInto(stage, source);
      })
      .then(function (svg) {
        stage.style.height = stageHeight(svg, stage.clientWidth) + "px";
        attachPanZoom(wrap, stage, svg, source);
      })
      .catch(function (err) {
        showFailure(wrap, stage, source, err);
        console.warn("[vs-diagram]", err);
      });
  }

  function scan() {
    var list = document.querySelectorAll("pre.vs-mermaid");
    for (var i = 0; i < list.length; i++) {
      build(list[i]);
    }
  }

  /* 明暗配色切换：mermaid 的配色写死在渲染产物里，必须重渲染 */
  var lastScheme = null;
  function watchPalette() {
    lastScheme = document.body.getAttribute("data-md-color-scheme");
    var mo = new MutationObserver(function () {
      var now = document.body.getAttribute("data-md-color-scheme");
      if (now === lastScheme || !window.mermaid) {
        return;
      }
      lastScheme = now;
      initMermaid();
      var wraps = document.querySelectorAll(".vs-diagram");
      for (var i = 0; i < wraps.length; i++) {
        (function (wrap) {
          var stage = wrap.querySelector(".vs-diagram__stage");
          var src = wrap._vsSource;
          if (!stage || !src) {
            return;
          }
          var bar = wrap.querySelector(".vs-diagram__bar");
          if (bar) {
            bar.remove();
          }
          renderInto(stage, src)
            .then(function (svg) {
              stage.style.height = stageHeight(svg, stage.clientWidth) + "px";
              attachPanZoom(wrap, stage, svg, src);
            })
            .catch(function (err) {
              showFailure(wrap, stage, src, err);
            });
        })(wraps[i]);
      }
    });
    mo.observe(document.body, {
      attributes: true,
      attributeFilter: ["data-md-color-scheme"]
    });
  }

  function boot() {
    scan();
    if (!window._vsPaletteWatched) {
      window._vsPaletteWatched = true;
      watchPalette();
    }
  }

  /* navigation.instant 下翻页不重载，material 用 document$ 通知换页 */
  if (typeof window.document$ !== "undefined" && window.document$.subscribe) {
    window.document$.subscribe(boot);
  } else if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", boot);
  } else {
    boot();
  }
})();

